const catalogue = new Map();
function add(id, name, folder, prefix, terminals, model, description, aliases = [], properties = {}) {
  const pins = terminals.map(([name, electrical_type = 'passive', side = 'left'], index) => ({
    logical_number: String(index + 1), name, electrical_type, side,
  }));
  if (catalogue.has(id)) throw new Error(`Duplicate symbol ${id}`);
  catalogue.set(id, {
    id, name, folder, reference_prefix: prefix,
    asset_kind: model === 'editor_primitive' ? 'editor_primitive' : model === 'diagram_only' ? 'diagram_block' : 'schematic_symbol',
    aliases, search_terms: [...new Set([name, ...aliases])],
    pin_numbering: 'logical_not_package', pins, drawing_description: description,
    simulation: {
      requirement: model,
      ready_to_simulate_from_this_manifest: false,
      note: model === 'primitive'
        ? 'Requires a value and a valid TinyCAD/SPICE mapping; no electrical model is generated by this inventory.'
        : model === 'builtin_instrument'
        ? 'Reuse the native TinyCAD tool/control configuration. A picture or ordinary library symbol alone does not implement the instrument.'
        : model === 'editor_primitive'
        ? 'Use the editor feature; do not turn connectivity primitives into decorative, electrically disconnected library symbols.'
        : model === 'diagram_only'
        ? 'Documentation block only; terminals are functional connections, not an asserted device pinout or executable model.'
        : 'A compatible model, parameters and pin mapping must be supplied and validated separately.',
    },
    configurable_properties: properties,
  });
}
