const words = text => [...new Set(text.split(/\s+/).filter(Boolean))];
const canonical = value => JSON.parse(JSON.stringify(value));
const generatedDate = '2026-11-10';
const handoff = {
  date: generatedDate,
  scope: 'Inventory and generation/extraction requirements only. No symbol geometry, device models, footprints or application subfolder feature is implemented.',
  folder_semantics: 'folder is a proposed slash-separated logical path, not a claim of support in the current TinyCAD library browser.',
  source_document_base: 'All source_document paths are relative to the repository root, including in standalone library files.',
  identity: 'id is stable within a library; extraction may deduplicate by canonical_symbol_id, but each library is complete and permits independent duplicate assets.',
  pin_contract: 'Logical terminal numbers and signal names are not physical package pinouts. Resolve real package pins from an authoritative device reference before generating package-specific symbols.',
  conventions: 'Prefer IEC/UK teaching symbols. Power pins and polarity should remain explicit. Built-in instruments, probes, independent waveform sources and voltage-controlled sources are excluded from symbol generation. Use existing_tools configuration with the native tool defaults.',
  existing_tools: 'existing_tools and existing_tool_ids refer to supplied non-library tools, not generation requirements. Never recreate these as library symbols.',
  inventory_not_bom: 'One record per reusable symbol type, not per component instance. A bridge can be assembled from repeated diode/resistor symbols. Different resistance/capacitance values are properties, not separate symbols.',
  model_warning: 'Every record is marked not ready to simulate from this manifest. A successful extraction of artwork does not establish a valid model, mapping or instrument implementation.',
  optionality: 'experiment_symbol_ids are a coverage set of proposed implementations and comparisons, not a minimal mandatory BOM; common support symbols and explicitly optional additions are separately identified.',
};

function parseActivities(text, sourceDocument) {
  const result = [];
  for (const line of text.split(/\r?\n/)) {
    if (!/^\| [A-Z]+\d{2} \|/.test(line)) continue;
    const cells = line.split('|').slice(1, -1).map(x => x.trim());
    const [id, title] = cells;
    const school = cells.length === 5;
    const semicolon = title.indexOf(';');
    result.push({
      id, title: school || semicolon < 0 ? title : title.slice(0, semicolon),
      syllabus_reference: school ? cells[2] : semicolon < 0 ? '' : title.slice(semicolon + 1).trim(),
      catalogue_support: cells[school ? 3 : 2],
      catalogue_description: cells[school ? 4 : 3],
      source_document: sourceDocument,
    });
  }
  return result;
}

const catalogueFile = 'library-sources/inventory/course-research.txt';
const catalogueText = await fs.readFile(path.join(root, catalogueFile), 'utf8');
const courseSections = new Map(
  [...catalogueText.matchAll(/^## ([a-z0-9-]+)\s*\n([\s\S]*?)(?=^## |(?![\s\S]))/gm)]
    .map(([, id, text]) => [id, text]),
);
await fs.mkdir(path.join(output, 'libraries'), {recursive: true});
const libraries = [];
for (const [libraryId, title, assignments, optional = {}] of courses) {
  const sourceText = courseSections.get(libraryId);
  if (!sourceText) throw new Error(`Missing catalogue section for ${libraryId}`);
  const sourceDocument = `${catalogueFile}#${libraryId}`;
  // Markdown reference IDs are course-prefixed to avoid collisions in the
  // combined document; standalone inventory references keep their local IDs.
  const activities = parseActivities(
    sourceText.replaceAll(`][${libraryId}-`, ']['), sourceDocument,
  );
  if (!activities.length) throw new Error(`No experiments in ${sourceDocument}`);
  const ids = new Set(activities.map(a => a.id));
  if (ids.size !== activities.length) throw new Error(`Duplicate experiment IDs in ${sourceDocument}`);
  for (const id of Object.keys(assignments)) if (!ids.has(id)) throw new Error(`Unknown experiment ${id}`);
  for (const activity of activities) {
    if (!assignments[activity.id]) throw new Error(`Unmapped experiment ${activity.id}`);
    const requested = words(assignments[activity.id]);
    activity.experiment_symbol_ids = requested.filter(id => !nativeTools[id]);
    activity.existing_tool_ids = requested.filter(id => nativeTools[id]);
  }
  const selected = new Set(allCommon);
  for (const a of activities) for (const id of [...a.experiment_symbol_ids, ...a.existing_tool_ids]) selected.add(id);
  for (const list of Object.values(optional)) for (const id of words(list)) selected.add(id);
  const existingTools = [...selected].filter(id => nativeTools[id]).map(id => ({
    id, name: catalogue.get(id).name, ...teachingNativeTools[id], already_provided: true, generate_symbol: false,
    used_by_experiments: activities.filter(a => a.existing_tool_ids.includes(id)).map(a => a.id),
    common_support_tool: allCommon.includes(id),
  }));
  for (const tool of existingTools) selected.delete(tool.id);
  const symbols = [...selected].map(id => {
    if (!catalogue.has(id)) throw new Error(`Unknown symbol ${id} in ${libraryId}`);
    const symbol = canonical(catalogue.get(id));
    const primitiveFamilies = {resistor: 'R', rheostat: 'R', capacitor: 'C', capacitor_polarised: 'C', capacitor_variable: 'C', inductor: 'L', cell: 'V', battery: 'V', source_dc: 'V', source_sine: 'V', source_pulse: 'V', source_pwl: 'V', source_fm: 'V', current_source: 'I', vcvs: 'E', vccs: 'G'};
    if (nativeTools[id]) symbol.simulation.native_tool = nativeTools[id];
    if (primitiveFamilies[id]) symbol.simulation.ngspice_family = primitiveFamilies[id];
    const usedBy = activities.filter(a => a.experiment_symbol_ids.includes(id)).map(a => a.id);
    const optionalFor = Object.entries(optional).filter(([, list]) => words(list).includes(id)).map(([name]) => name);
    const pinIds = new Set(symbol.pins.map(p => p.logical_number));
    if (pinIds.size !== symbol.pins.length) throw new Error(`Duplicate pins in ${id}`);
    return {...symbol, canonical_symbol_id: id, used_by_experiments: usedBy,
      common_support_symbol: common.includes(id), optional_uses: optionalFor,
      library_requirement: usedBy.length ? 'experiment_coverage' : common.includes(id) ? 'common_support' : 'optional_extension',
    };
  }).sort((a,b) => a.folder.localeCompare(b.folder, 'en') || a.id.localeCompare(b.id, 'en'));
  const sources = [...sourceText.matchAll(/^\[([^\]]+)\]:\s+(https?:\S+)/gm)].map(([, id, url]) => ({id: id.replace(`${libraryId}-`, ''), url}));
  const library = {
    $schema: '../symbol-library.schema.json', schema_version: '1.0.0', manifest_kind: 'library',
    library_id: libraryId, title, source_document: sourceDocument, handoff,
    syllabus_sources: sources,
    common_symbol_ids: common,
    existing_tools: existingTools,
    folders: [...new Set(symbols.map(s => s.folder))].sort(),
    experiments: activities, symbols,
  };
  libraries.push(library);
  await fs.writeFile(path.join(output, 'libraries', `${libraryId}.json`), `${JSON.stringify(library, null, 2)}\n`);
}

const distinct = new Set(libraries.flatMap(l => l.symbols.map(s => s.id)));
const manifest = {$schema: 'symbol-library.schema.json', schema_version: '1.0.0', manifest_kind: 'collection', handoff,
  totals: {libraries: libraries.length, experiments: libraries.reduce((n,l) => n+l.experiments.length,0),
    library_symbol_records: libraries.reduce((n,l) => n+l.symbols.length,0), distinct_symbol_types: distinct.size},
  libraries: libraries.map(l => {const copy = canonical(l); delete copy.$schema; return copy;}),
};
await fs.writeFile(path.join(output, 'library-manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`);
const uniqueSymbols = new Map();
for (const library of libraries) for (const symbol of library.symbols) {
  const {used_by_experiments, common_support_symbol, optional_uses, library_requirement, ...definition} = symbol;
  const existing = uniqueSymbols.get(symbol.canonical_symbol_id);
  if (existing && JSON.stringify(existing.definition) !== JSON.stringify(definition))
    throw new Error(`Conflicting definitions for ${symbol.canonical_symbol_id}`);
  const entry = existing || {definition, usages: []};
  entry.usages.push({library_id: library.library_id, used_by_experiments, common_support_symbol, optional_uses, library_requirement});
  uniqueSymbols.set(symbol.canonical_symbol_id, entry);
}
const deduplicated = [...uniqueSymbols.values()].map(({definition, usages}) => ({
  ...definition,
  used_by_experiments: [...new Set(usages.flatMap(u => u.used_by_experiments))],
  common_support_symbol: usages.some(u => u.common_support_symbol),
  optional_uses: [...new Set(usages.flatMap(u => u.optional_uses))],
  library_requirement: usages.some(u => u.used_by_experiments.length) ? 'experiment_coverage' : usages.some(u => u.common_support_symbol) ? 'common_support' : 'optional_extension',
  used_by_libraries: usages.map(u => u.library_id),
  library_usage: usages,
})).sort((a,b) => a.folder.localeCompare(b.folder, 'en') || a.id.localeCompare(b.id, 'en'));
const uniqueManifest = {
  $schema: 'symbol-library.schema.json', schema_version: '1.0.0', manifest_kind: 'deduplicated_symbols', handoff,
  totals: {unique_symbols: deduplicated.length, source_libraries: libraries.length, experiments: manifest.totals.experiments},
  source_libraries: libraries.map(({library_id, title, source_document}) => ({library_id, title, source_document})),
  symbols: deduplicated,
  existing_tools: Object.entries(teachingNativeTools).map(([id, tool]) => ({
    id, name: catalogue.get(id).name, ...tool, already_provided: true, generate_symbol: false,
    used_by_libraries: libraries.filter(l => l.existing_tools.some(t => t.id === id)).map(l => l.library_id),
    used_by_experiments: [...new Set(libraries.flatMap(l => l.existing_tools.find(t => t.id === id)?.used_by_experiments || []))],
    common_support_tool: allCommon.includes(id),
  })),
};
await fs.writeFile(path.join(output, 'all-symbols.json'), `${JSON.stringify(uniqueManifest, null, 2)}\n`);
const csv = rows => rows.map(row => row.map(value => `"${String(value).replaceAll('"', '""')}"`).join(',')).join('\r\n') + '\r\n';
const uniqueRows = [['symbol_id','name','folder','asset_kind','reference_prefix','aliases_json','logical_pins_json','drawing_description','simulation_json','configurable_properties_json','requirement','used_by_libraries_json','used_by_experiments_json','library_usage_json']];
for (const s of deduplicated) uniqueRows.push([s.id,s.name,s.folder,s.asset_kind,s.reference_prefix,JSON.stringify(s.aliases),JSON.stringify(s.pins),s.drawing_description,JSON.stringify(s.simulation),JSON.stringify(s.configurable_properties),s.library_requirement,JSON.stringify(s.used_by_libraries),JSON.stringify(s.used_by_experiments),JSON.stringify(s.library_usage)]);
await fs.writeFile(path.join(output, 'all-symbols.csv'), csv(uniqueRows));
const csvRows = [['library_id','library_title','symbol_id','folder','name','asset_kind','requirement','aliases_json','reference_prefix','logical_pins_json','drawing_description','simulation_requirement','configurable_properties_json','used_by_experiments','common_support_symbol','optional_uses_json']];
const usageRows = [['library_id','experiment_id','experiment_title','syllabus_reference','catalogue_support','symbol_ids_json','common_symbol_ids_json','existing_tool_ids_json','common_existing_tool_ids_json','source_document']];
for (const library of libraries) {
  for (const s of library.symbols) csvRows.push([library.library_id,library.title,s.id,s.folder,s.name,s.asset_kind,s.library_requirement,JSON.stringify(s.aliases),s.reference_prefix,JSON.stringify(s.pins),s.drawing_description,s.simulation.requirement,JSON.stringify(s.configurable_properties),s.used_by_experiments.join(';'),s.common_support_symbol,JSON.stringify(s.optional_uses)]);
  for (const a of library.experiments) usageRows.push([library.library_id,a.id,a.title,a.syllabus_reference,a.catalogue_support,JSON.stringify(a.experiment_symbol_ids),JSON.stringify(library.common_symbol_ids),JSON.stringify(a.existing_tool_ids),JSON.stringify(library.existing_tools.filter(t => t.common_support_tool).map(t => t.id)),a.source_document]);
}
await fs.writeFile(path.join(output, 'symbols.csv'), csv(csvRows));
await fs.writeFile(path.join(output, 'experiment-symbol-map.csv'), csv(usageRows));
